void Solver::rephase() {
    // 1. Reset the rephase counter – start a fresh rephase cycle.
    rephases = 0;

    // 2. Make the trail‑size threshold more aggressive.
    //    Reduce it by 15 % but never let it drop below the number of variables
    //    (so we keep a reasonable lower bound).
    threshold = std::max((int)(threshold * 0.85), vars);

    // 3. Grow the rephase limit adaptively.
    //    Add a base increment (4096) plus half of the current limit.
    //    This lets the solver stay longer in a rephase‑rich phase when it is
    //    making progress, but still forces a new rephase eventually.
    rephase_limit += 4096 + rephase_limit / 2;

    // 4. Diversify the saved phases after a rephase.
    //    Randomly choose one of three strategies:
    //      – reuse the best local phase,
    //      – use the opposite of the best local phase,
    //      – pick a completely random polarity.
    int mode = rand() % 3;
    if (mode == 0) {
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (mode == 1) {
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() % 2) ? 1 : -1;
    }
}
